#pragma once
#include "Prelude.h"

namespace finals_core {
// Empty result means a cycle unless the input graph is empty.
inline vi topological_order(const Graph &g) {
	int n = int(g.size());
	vi deg(n), order;
	for (const auto &adj : g)
		for (int v : adj) ++deg[v];
	queue<int> q;
	for (int u = 0; u < n; ++u)
		if (!deg[u]) q.push(u);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		order.push_back(u);
		for (int v : g[u])
			if (--deg[v] == 0) q.push(v);
	}
	if (int(order.size()) != n) return {};
	return order;
}
} // namespace finals_core
